window.futvizVista("xa-vs-asistencias-90","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"xa-vs-asistencias-90\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"xa-vs-asistencias-90\"]={\"id\":\"xa-vs-asistencias-90\",\"titulo\":\"xA vs. asistencias por 90'\",\"bajada\":\"Sobre la diagonal dio m\u00e1s asistencias que su xA; a la derecha de la l\u00ednea, el 20% con m\u00e1s xA.\",\"pregunta\":\"\u00bfQui\u00e9n da m\u00e1s asistencias de las que deber\u00eda?\",\"tabla\":\"jugadores\",\"entidad\":\"jugadores\",\"x\":{\"col\":\"xA90\",\"label\":\"xA por 90'\",\"corto\":\"xA por 90'\",\"dec\":2},\"y\":{\"col\":\"a90\",\"label\":\"Asistencias por 90'\",\"corto\":\"Asistencias por 90'\",\"dec\":2},\"referencia\":{\"tipo\":\"diagonal\",\"dif\":\"asistencias \u2212 xA por 90'\",\"sobre\":\"Asisten m\u00e1s de lo esperado\",\"bajo\":\"Asisten menos de lo esperado\",\"decDif\":2,\"zonas\":{\"pct\":0.8,\"variable\":\"xA por 90'\",\"tl\":\"Crean poco pero les anotan\",\"tr\":\"Crean mucho y les anotan\",\"bl\":\"Crean poco y les fallan\",\"br\":\"Crean mucho pero les fallan\"}},\"requiere\":[\"xA90\",\"a90\"],\"subtitulo\":\"Jugadores con \u2265{min} min \u00b7 {temporada}\",\"filtros\":{\"posicion\":true,\"nivel\":true,\"sub21\":true},\"metricas\":[{\"id\":\"x\",\"etiqueta\":\"xA por 90'\",\"ayuda\":\"Ordenados por xA por 90'\"},{\"id\":\"y\",\"etiqueta\":\"Asistencias por 90'\",\"ayuda\":\"Ordenados por Asistencias por 90'\"}],\"queMirar\":\"Compara las asistencias que da cada jugador con las que val\u00edan sus pases. El xA, en el eje horizontal, mide el peligro de sus pases de gol, es decir, la probabilidad de que el tiro que habilit\u00f3 termine en gol, y en el vertical est\u00e1n las asistencias reales, ambas por 90 minutos.\\nSobre la diagonal, sus compa\u00f1eros convirtieron m\u00e1s de lo esperado y debajo, menos. La l\u00ednea vertical separa al 20% de jugadores con m\u00e1s xA, los que m\u00e1s peligro crean con sus pases.\",\"insight\":\"xa_asist_90\",\"fuente\":\"Understat\",\"colorPor\":[\"liga\",\"rendimiento\"],\"minimoPor90\":true,\"posicionesIni\":[\"Defensa\",\"Medio\",\"Delantero\"]};</script>");